  ui_story_5089_50890700_63_dialog_content = "ดูเหมือนว่าชื่อเสียงของคุณในฐานะดาบที่คมกริบที่สุดของพระราชาได้รับอย่างคุ้มค่า",
  ui_story_5089_50890700_64_dialog_content = "ไม่มีนักรบใดในวังทั้งหมดที่หวังว่าจะสามารถเทียบเคียงกับคุณได้เลย",
