  ui_story_5089_50890700_73_dialog_content = "คุณจริงๆ แล้วคือนักสู้ดาบที่ทรงพลังที่สุดในการควบคุมของฉัน",
  ui_story_5089_50890700_74_dialog_content = "อะไรกัน...!",
  ui_story_5089_50890700_75_dialog_content = "ยาม! ทักทายผู้บังคับบัญชาด้วยการทดสอบความแข็งแกร่งอย่างเป็นมิตร!",
  ui_story_5089_50890700_76_dialog_content = "รับทราบ เจ้าหญิง!",
  ui_story_5089_50890700_77_dialog_content = "<color=#e8d9bb>ทหารยามเงาของพระราชาเข้ามาจากทั้งสองฝั่ง สายเหล็กที่คมบางของพวกเขาตัดผ่าอากาศ</color>",
  ui_story_5089_50890700_78_dialog_content = "<color=#e8d9bb>ในขณะที่จิ่วกำลังจะหลบหลีก นางสังเกตเห็นช่องโหว่ในการป้องกันของราชาปลอมและโจมตี</color>",
  ui_story_5089_50890700_79_dialog_content = "—!",
  ui_story_5089_50890700_80_dialog_content = "<color=#e8d9bb>ลวดโลหะแทงเข้าสู่ขาของเธอที่ต่ำกว่า แต่การโจมตีของเธอไม่สั่นสะเทือนเลยแม้แต่ชั่วขณะ เธอแทงดาบของเธอตรงไปที่หัวใจของราชาที่เป็นเท็จด้วยความแข็งแกร่งทั้งหมดของเธอ!</color>",
  ui_story_5089_50890700_81_dialog_content = "ตั้งแต่เธอยังเป็นเด็ก ๆ เธอก็มีนิสัยไม่ดีนี้มาตลอดเลย",
