  ui_story_5089_50890700_86_dialog_content = "ดาบของคุณคมจริง แต่การลับคมให้ถึงขีดจำกัดจะทำให้ความทนทานของดาบลดลง",
  ui_story_5089_50890700_87_dialog_content = "คุณลืมเหตุผลที่ฉันให้ชื่อคุณว่า \"จิ่ว\" ไปหรือเปล่า?",
  ui_story_5089_50890700_88_dialog_content = "!",
  ui_story_5089_50890700_89_dialog_content = "<color=#e8d9bb>—เมื่อสิบปีที่ผ่านมา</color>",
