  ui_story_5089_50890700_92_dialog_content = "แต่ดูคุณตอนนี้สิ: หิวโหย, ตัวเต็มไปด้วยแผลพุพอง, และแทบจะยืนไม่ไหวแล้ว",
  ui_story_5089_50890700_93_dialog_content = "แม้คุณจะไล่ทันศัตรูในสภาพนี้ ชัยชนะที่คุณหวังไว้ก็เพียงแค่ความตายของทั้งคู่เท่านั้น",
  ui_story_5089_50890700_94_dialog_content = "... แต่นั่นไม่ได้ทำให้คุณรำคาญใช่ไหม? สุดท้ายแล้วคุณจะทำอะไรได้บ้างนอกจากการสละชีวิตเพื่อแก้แค้น?",
  ui_story_5089_50890700_95_dialog_content = "แต่ตอนนี้หลังจากที่ฉันได้ช่วยแก้แค้นให้เธอแล้ว มันก็เหมาะสมที่ชีวิตของเธอจะเป็นของฉันเท่านั้นแล้ว",
  ui_story_5089_50890700_96_dialog_content = "\"จิ่ว-เมย์,\" ใช่ไหม? ชื่อที่หมายถึง \"ลูกสาวคนที่เก้า\" ก็แทบจะไม่มีค่าควรเก็บรักษาเลย",
  ui_story_5089_50890700_97_dialog_content = "ตั้งแต่วันนี้เป็นต้นไป คุณจะถูกเรียกว่า \"จิ่ว\" อย่างเดียว.",
  ui_story_5089_50890700_98_dialog_content = "ชื่อที่อ้างถึงหินมรกตสีดำที่บริสุทธิ์ที่สุด มันสวยงามเท่ากับหยก แต่แข็งแกร่งกว่ามาก",
  ui_story_5089_50890700_99_dialog_content = "ภายใต้การสั่งการของฉัน คุณจะฝึกฝนความคมของคุณและกลายเป็นดาบที่คมที่สุดของฉัน ถ้าคุณไม่ทำให้ตัวเองกลายเป็นแข็งแรงแต่บอบบาง",
  ui_story_5089_50890700_100_dialog_content = "<color=#e8d9bb>จิ่วสูญเสียความสนใจชั่วขณะ แล้วถูกตรึงลงพื้นทันทีด้วยเครือข่ายสายลวดโลหะนับไม่ถ้วน</color>",
  ui_story_5089_50890700_101_dialog_content = "<color=#e8d9bb>หน้ากากของเธอตกลงสู่พื้น แต่เธอยังคงมองอย่างขมขื่นไปที่กษัตริย์อันปลอมปรอง</color>",
