  ui_story_5089_50890700_107_dialog_content = "คำทำนายอันน่าหวั่นของ PlayerName ที่ได้รับมาก่อนหน้านี้ ตรงกับสถานการณ์ปัจจุบันของเราอย่างแม่นยำ",
