  ui_story_5089_50890700_136_dialog_content = "และดังนั้นเขาก็ฆ่าพวกเขาโดยไม่คิดค้น และดำเนินต่อไปตามเส้นทางเดิมของเขาไปยังค่ายแรงงาน",
