  ui_story_5089_50891201_73_dialog_content = "(อาวุธ, กิ่งไม้, ใบไม้, หิน, และแม้กระทั่งซากประกอบของสัตว์เครื่องลานที่ถูกสังหาร...)",
  ui_story_5089_50891201_74_dialog_content = "(วัตถุใด ๆ ที่อยู่ในสายตาของจิ่วมีศักยภาพที่จะกลายเป็นอาวุธทรงพลัง ถ้าเธอมีอะไรอยู่ในมือ เธอก็หยุดไม่อยู่)",
  ui_story_5089_50891201_75_dialog_content = "รวดเร็วเหมือนนักธนูตำนานที่ยิงลงพระอาทิตย์เก้าดวง และสง่างามเหมือนจักรพรรดิที่ยืนอยู่บนมังกรที่ทะยานขึ้นสู่ท้องฟ้า",
  ui_story_5089_50891201_76_dialog_content = "ลงมายังสนามรบเหมือนพายุที่กำลังรวมตัว เธอแยกทหารออกเป็นสองฝั่งเหมือนฟ้าผ่าที่สว่างที่สุด",
  ui_story_5089_50891201_77_dialog_content = "จิ่ว คุณได้ค้นพบใบมีดที่แท้จริงของคุณแล้วหรือยัง?",
