  ui_story_5089_50891201_81_dialog_content = "<color=#e8d9bb>แต่จิ่วปรากฏตัวทันทีเบื้องหลังเธอก่อนที่เธอจะสามารถเรียกสัตว์เครื่องปั่นเพิ่มเติม</color>",
  ui_story_5089_50891201_82_dialog_content = "อยู่เฉย ๆ ไปน่ะดีแล้ว",
  ui_story_5089_50891201_83_dialog_content = "!",
