  ui_story_5089_50891201_85_dialog_content = "ตราบใดที่ Fate Riders สามารถเรียกคืนเข็มที่มีพลังทั้งหมดของฉันได้ มันจะยังคงทำลายล้างทั่วสนามรบ!",
