  ui_story_5089_50891201_97_dialog_content = "เขาอ้างว่าเขาไม่มีวิธีสอนฉัน ใช่ ในตอนแรกฉันคิดว่าเขาแค่หาข้ออ้าง",
  ui_story_5089_50891201_98_dialog_content = "แต่ตอนนี้ฉันเริ่มเห็นว่าเขาถูกต้องมาตลอดเลย",
