  ui_story_5089_50891201_133_dialog_content = "\"จักรวาลปฏิบัติตามกฎหมายห้าสิบข้อ แต่สวรรค์ซ่อนความลับสี่สิบเก้าข้อ ทิ้งเส้นทางเดียวให้มนุษยชาติ\"",
