  ui_story_5089_50891201_143_dialog_content = "ถ้าเป็นเช่นนั้น เราก็จะขาดความหมายไปหากไม่มีพวกเขา",
  ui_story_5089_50891201_144_dialog_content = "แม้ว่าเราจะหลงทาง ตกอยู่ในความมืดมิด หรือจำตัวเองในกรงความโง่เขลา แต่เรายังสามารถพบกับผู้คนที่มีความเมตตาและอบอุ่นไร้ขีดจำกัดได้เสมอ",
